`timescale 1ns/1ps
module tb_shake;
reg clk=0, rst_n=0; always #5 clk=~clk;
reg init=0, mode=0, in_valid=0, finalize=0, out_take=0; reg [7:0] in_byte=0; wire in_ready, out_ready, idle; wire [7:0] out_byte;
shake_unit dut(clk,rst_n,init,mode,in_valid,in_byte,in_ready,finalize,out_take,out_ready,out_byte,idle);
integer fails=0, n=0, j; reg [4095:0] got; reg [7:0] b;
task run(input m, input [4095:0] d, input integer il, input integer ol, input [4095:0] exp); begin
  @(negedge clk); mode=m; init=1; @(negedge clk); init=0; @(negedge clk);
  for (j=0;j<il;j=j+1) begin while(!in_ready) @(negedge clk); in_valid=1; in_byte=d[4095-8*j -: 8]; @(negedge clk); in_valid=0; end
  while(!in_ready) @(negedge clk); finalize=1; @(negedge clk); finalize=0;
  for (j=0;j<ol;j=j+1) begin while(!out_ready) @(negedge clk); got[4095-8*j -: 8]=out_byte; out_take=1; @(negedge clk); out_take=0; end
  n=n+1; if ((got >> (4096-8*ol)) !== (exp >> (4096-8*ol))) begin fails=fails+1; $display("FAIL mode=%0d il=%0d ol=%0d",m,il,ol); end end endtask
initial begin #30 rst_n=1; #30;
  run(0,4096',0,1,4096');
  run(0,4096',0,32,4096');
  run(0,4096',0,500,4096');
  run(0,4096',1,1,4096');
  run(0,4096',1,32,4096');
  run(0,4096',1,500,4096');
  run(0,4096',7,1,4096');
  run(0,4096',7,32,4096');
  run(0,4096',7,200,4096');
  run(0,4096',7,500,4096');
  run(0,4096',8,32,4096');
  run(0,4096',8,200,4096');
  run(0,4096',8,500,4096');
  run(0,4096',9,32,4096');
  run(0,4096',9,200,4096');
  run(0,4096',100,1,4096');
  run(0,4096',100,32,4096');
  run(0,4096',100,500,4096');
  run(0,4096',135,32,4096');
  run(0,4096',135,500,4096');
  run(0,4096',136,1,4096');
  run(0,4096',136,32,4096');
  run(0,4096',136,200,4096');
  run(0,4096',137,32,4096');
  run(0,4096',167,32,4096');
  run(0,4096',167,200,4096');
  run(0,4096',167,500,4096');
  run(0,4096',168,32,4096');
  run(0,4096',169,1,4096');
  run(0,4096',169,32,4096');
  run(0,4096',169,200,4096');
  run(0,4096',169,500,4096');
  run(0,4096',300,32,4096');
  run(0,4096',300,500,4096');
  run(1,4096',0,1,4096');
  run(1,4096',0,32,4096');
  run(1,4096',0,200,4096');
  run(1,4096',0,500,4096');
  run(1,4096',1,1,4096');
  run(1,4096',1,32,4096');
  run(1,4096',7,32,4096');
  run(1,4096',8,32,4096');
  run(1,4096',9,1,4096');
  run(1,4096',9,32,4096');
  run(1,4096',9,500,4096');
  run(1,4096',100,1,4096');
  run(1,4096',100,32,4096');
  run(1,4096',135,1,4096');
  run(1,4096',135,32,4096');
  run(1,4096',135,500,4096');
  run(1,4096',136,32,4096');
  run(1,4096',136,500,4096');
  run(1,4096',137,1,4096');
  run(1,4096',137,32,4096');
  run(1,4096',137,500,4096');
  run(1,4096',167,32,4096');
  run(1,4096',168,1,4096');
  run(1,4096',168,32,4096');
  run(1,4096',169,1,4096');
  run(1,4096',169,32,4096');
  run(1,4096',169,200,4096');
  run(1,4096',300,32,4096');
  run(1,4096',300,500,4096');
  if (fails==0) $display("ALL PASS (%0d cases)", n); else $display("FAILED %0d", fails);
  $finish;
end
initial begin #500000000 $display("TIMEOUT"); $finish; end
endmodule
